import { useState, useEffect, useRef, useCallback } from "react";

/**
 * App — アルティメット(フリスビー)のスタッツ集計アプリ（TypeScript版・フル機能）
 *
 * 使い方:
 *   import App from "./App";
 *   <App />
 *
 * 依存ライブラリなし（React標準のHooksのみ）。CSSはコンポーネント内の<style>タグに
 * 同梱しているので、このファイル1つをプロジェクトに置くだけで動作します。
 * データはブラウザのlocalStorageに自動保存されます。
 *
 * 含まれる機能:
 *   - 大会 > 試合 > 選手 の階層管理、大会全体の集計
 *   - タッチ数・スローミス・キャッチミス・ブロック・ゴール・アシストのタップ入力、元に戻す
 *   - 背番号順 / 登録順 ソート切り替え、NO・選手列の分割表示
 *   - 出場メンバーの絞り込み、絞り込み条件を「グループ」として大会単位で保存・再利用
 *   - 他の試合から選手をコピー
 *   - CSV書き出し（ブラウザの標準ダウンロード）／ PDF書き出し（印刷ダイアログ）
 */

// ---------------- Types ----------------

type StatKey = "touch" | "throwMiss" | "catchMiss" | "block" | "goal" | "assist";

interface PlayerStats {
  touch: number;
  throwMiss: number;
  catchMiss: number;
  block: number;
  goal: number;
  assist: number;
}

interface Player extends PlayerStats {
  id: string;
  name: string;
  number: string;
  mom?: boolean; // その試合のマンオブザマッチ
}

interface MatchGroup {
  id: string;
  name: string;
  memberNames: string[];
}

interface MatchData {
  id: string;
  name: string;
  players: Player[];
  activeFilterNames?: string[] | null;
}

interface RosterColumn {
  id: string;
  name: string;
  locked?: boolean; // 背番号・名前の最初の2列はロック（削除不可）
}

interface RosterRow {
  id: string;
  values: Record<string, string>; // key = RosterColumn.id
}

interface RosterData {
  columns: RosterColumn[];
  rows: RosterRow[];
}

interface TournamentAward {
  id: string;
  name: string;
  playerName: string; // 空文字 = 未選出。同じ選手が複数の賞を受賞してもよい
}

interface TournamentData {
  id: string;
  name: string;
  matches: MatchData[];
  activeMatchId: string;
  groups: MatchGroup[];
  roster: RosterData;
  awards: TournamentAward[];
}

interface AppState {
  tournaments: TournamentData[];
  activeTournamentId: string;
  mode: "add" | "sub";
  sortMode: "reg" | "number";
  headerCollapsed?: boolean;
  themeColor?: string;
}

interface LastAction {
  matchId: string;
  playerId: string;
  field: StatKey;
  delta: number;
}

interface UIState {
  addPlayerOpen: boolean;
  newMatchOpen: boolean;
  newTournamentOpen: boolean;
  renamingMatch: boolean;
  renamingTournament: boolean;
  editingPlayerId: string | null;
  confirmDeleteMatch: string | null;
  confirmDeleteTournament: string | null;
  confirmDeletePlayer: string | null;
  copyOpen: boolean;
  copySourceKey: string | null;
  copySelected: Record<string, boolean>;
  filterOpen: boolean;
  filterDraft: Record<string, boolean>;
  filterLoadedGroupId: string | null;
  savingGroupNameOpen: boolean;
  confirmDeleteGroup: string | null;
  addingRosterColumn: boolean;
  aggSortKey: string | null;
  aggSortDir: "asc" | "desc";
  aggExtraColumnIds: string[];
  aggColumnFilters: Record<string, string>;
  addingAward: boolean;
  helpOpen: boolean;
  rosterCsvFile: File | null;
  rosterPickOpen: boolean;
  rosterPickSelected: Record<string, boolean>;
  fullCsvFile: File | null;
}

// ---------------- Constants ----------------

const STORAGE_KEY = "ultimateStatsAppTsxV1";
const ALL_ID = "__ALL__";
const ROSTER_ID = "__ROSTER__";
const SETTINGS_ID = "__SETTINGS__";
const DEFAULT_PITCH = "#1B4332";

function defaultAwards(): TournamentAward[] {
  return ["MVP", "敢闘賞", "アシスト王", "得点王", "スコアリーダー"].map((name) => ({ id: uid(), name, playerName: "" }));
}

// 16進カラーをpercentぶん黒(negative)/白(positive)側に寄せる（ヘッダー用の濃色バリエーション生成に使用）
function shadeColor(hex: string, percent: number): string {
  const m = hex.replace("#", "");
  const num = parseInt(m.length === 3 ? m.split("").map((c) => c + c).join("") : m, 16);
  let r = (num >> 16) & 0xff, g = (num >> 8) & 0xff, b = num & 0xff;
  const t = percent < 0 ? 0 : 255;
  const p = Math.abs(percent);
  r = Math.round((t - r) * p) + r;
  g = Math.round((t - g) * p) + g;
  b = Math.round((t - b) * p) + b;
  return "#" + [r, g, b].map((v) => Math.max(0, Math.min(255, v)).toString(16).padStart(2, "0")).join("");
}

const AGG_ICON = "data:image/png;base64,";
const TROPHY_ICON = "data:image/png;base64,";

function defaultRoster(): RosterData {
  return {
    columns: [
      { id: "number", name: "背番号", locked: true },
      { id: "name", name: "名前", locked: true },
    ],
    rows: [],
  };
}

const FIELDS: { key: StatKey; label: string; kind: "neutral" | "miss" | "good" }[] = [
  { key: "touch", label: "タッチ数", kind: "neutral" },
  { key: "throwMiss", label: "スローミス", kind: "miss" },
  { key: "catchMiss", label: "キャッチミス", kind: "miss" },
  { key: "block", label: "ブロック", kind: "good" },
  { key: "goal", label: "ゴール", kind: "good" },
  { key: "assist", label: "アシスト", kind: "good" },
];

// ---------------- Helpers ----------------

function uid(): string {
  return Date.now().toString(36) + Math.random().toString(36).slice(2, 7);
}

function todayLabel(): string {
  const d = new Date();
  return `${d.getFullYear()}/${d.getMonth() + 1}/${d.getDate()}`;
}

function pad2(n: number): string {
  return (n < 10 ? "0" : "") + n;
}

function blankPlayerStats(): PlayerStats {
  return { touch: 0, throwMiss: 0, catchMiss: 0, block: 0, goal: 0, assist: 0 };
}

function defaultMatch(name?: string): MatchData {
  return { id: uid(), name: name || `${todayLabel()} 試合`, players: [], activeFilterNames: null };
}

function defaultTournament(name?: string): TournamentData {
  const m = defaultMatch();
  return { id: uid(), name: name || `${todayLabel()} 大会`, matches: [m], activeMatchId: m.id, groups: [], roster: defaultRoster(), awards: defaultAwards() };
}

function defaultState(): AppState {
  const t = defaultTournament();
  return { tournaments: [t], activeTournamentId: t.id, mode: "add", sortMode: "reg", headerCollapsed: false };
}

function loadState(): AppState {
  try {
    const raw = window.localStorage.getItem(STORAGE_KEY);
    if (!raw) return defaultState();
    const parsed = JSON.parse(raw);
    if (parsed && Array.isArray(parsed.tournaments) && parsed.tournaments.length > 0) {
      parsed.tournaments.forEach((t: TournamentData) => {
        if (!Array.isArray(t.groups)) t.groups = [];
        if (!t.roster || !Array.isArray(t.roster.columns)) t.roster = defaultRoster();
        if (!Array.isArray(t.awards)) t.awards = defaultAwards();
      });
      return parsed;
    }
    return defaultState();
  } catch (e) {
    return defaultState();
  }
}

function calcRate(attempts: number, misses: number): number | null {
  attempts = attempts || 0;
  misses = misses || 0;
  if (attempts <= 0) return null;
  return Math.max(0, Math.round(((attempts - misses) / attempts) * 100));
}
function passRate(p: PlayerStats): number | null {
  return calcRate(p.touch || 0, (p.throwMiss || 0) + (p.catchMiss || 0));
}
function fmtRate(v: number | null): string {
  return v === null ? "—" : v + "%";
}

function sortPlayers<T extends { number: string }>(list: T[], sortMode: "reg" | "number"): T[] {
  if (sortMode !== "number") return list;
  return [...list].sort((a, b) => {
    const an = parseFloat(a.number);
    const bn = parseFloat(b.number);
    const av = a.number !== "" && a.number != null && !isNaN(an);
    const bv = b.number !== "" && b.number != null && !isNaN(bn);
    if (av && bv) return an - bn;
    if (av) return -1;
    if (bv) return 1;
    return 0;
  });
}

function csvEscape(v: unknown): string {
  const s = String(v == null ? "" : v);
  if (/[",\n]/.test(s)) return '"' + s.replace(/"/g, '""') + '"';
  return s;
}

function parseCSVLine(line: string): string[] {
  const result: string[] = [];
  let cur = "";
  let inQuotes = false;
  for (let i = 0; i < line.length; i++) {
    const ch = line[i];
    if (inQuotes) {
      if (ch === '"') {
        if (line[i + 1] === '"') { cur += '"'; i++; } else { inQuotes = false; }
      } else { cur += ch; }
    } else {
      if (ch === '"') inQuotes = true;
      else if (ch === ",") { result.push(cur); cur = ""; }
      else cur += ch;
    }
  }
  result.push(cur);
  return result;
}

// ヘッダー付きCSVを解析し、ヘッダー名をキーにしたオブジェクトの配列で返す
function parseCSVWithHeader(text: string): { headers: string[]; rows: Record<string, string>[] } {
  const lines = text.split(/\r\n|\n|\r/).filter((l) => l.trim().length > 0);
  if (!lines.length) return { headers: [], rows: [] };
  const headers = parseCSVLine(lines[0]).map((h) => h.trim());
  const rows = lines.slice(1).map((line) => {
    const parts = parseCSVLine(line);
    const obj: Record<string, string> = {};
    headers.forEach((h, i) => { obj[h] = (parts[i] || "").trim(); });
    return obj;
  });
  return { headers, rows };
}

function truthyFlag(v: string): boolean {
  const s = (v || "").trim();
  return s === "○" || s === "TRUE" || s === "true" || s === "1" || s === "はい" || s === "済";
}

// 先頭セルが空欄または数値なら「ヘッダー無し（もうデータ行）」、それ以外の文字列ならヘッダー行とみなす
function isLikelyHeaderCell(v: string): boolean {
  const s = (v || "").trim();
  if (s === "") return false;
  return isNaN(Number(s));
}

function sanitizeFilename(name: string): string {
  return (name || "アルティメット").replace(/[\/\\:*?"<>|]/g, "-").slice(0, 80);
}

function downloadTextFile(text: string, filename: string, mime: string) {
  const blob = new Blob([text], { type: mime });
  const url = URL.createObjectURL(blob);
  const a = document.createElement("a");
  a.href = url;
  a.download = filename;
  document.body.appendChild(a);
  a.click();
  document.body.removeChild(a);
  setTimeout(() => URL.revokeObjectURL(url), 2000);
}

interface AggRow extends PlayerStats {
  name: string;
  number: string;
  games: number;
}

function aggregateTournament(t: TournamentData, sortMode: "reg" | "number"): AggRow[] {
  const map: Record<string, AggRow> = {};
  const order: string[] = [];
  t.matches.forEach((m) => {
    m.players.forEach((p) => {
      const key = (p.name || "").trim();
      if (!key) return;
      if (!map[key]) {
        map[key] = { name: p.name, number: p.number || "", touch: 0, throwMiss: 0, catchMiss: 0, block: 0, goal: 0, assist: 0, games: 0 };
        order.push(key);
      }
      const a = map[key];
      a.touch += p.touch || 0;
      a.throwMiss += p.throwMiss || 0;
      a.catchMiss += p.catchMiss || 0;
      a.block += p.block || 0;
      a.goal += p.goal || 0;
      a.assist += p.assist || 0;
      a.games += 1;
      if (!a.number && p.number) a.number = p.number;
    });
  });
  const rows = order.map((k) => map[k]);
  if (sortMode === "number") return sortPlayers(rows, sortMode);
  return rows.sort((a, b) => b.touch - a.touch);
}

// 名簿の列を選手名で突き合わせて値を取得（見つからなければ空文字）
function joinRosterValue(roster: RosterData, colId: string, playerName: string): string {
  const target = playerName.trim();
  const row = roster.rows.find((r) => (r.values["name"] || "").trim() === target);
  return row ? (row.values[colId] || "") : "";
}

function sortAggRows(rows: AggRow[], key: string | null, dir: "asc" | "desc", roster: RosterData): AggRow[] {
  if (!key) return rows;
  const factor = dir === "asc" ? 1 : -1;
  return [...rows].sort((a, b) => {
    if (key === "name") return factor * a.name.localeCompare(b.name, "ja");
    if (key === "number") {
      const an = parseFloat(a.number), bn = parseFloat(b.number);
      const av = a.number !== "" && !isNaN(an), bv = b.number !== "" && !isNaN(bn);
      if (av && bv) return factor * (an - bn);
      if (av) return -1;
      if (bv) return 1;
      return 0;
    }
    if (key === "passRate") {
      const av = passRate(a) ?? -1, bv = passRate(b) ?? -1;
      return factor * (av - bv);
    }
    if (key === "games" || (FIELDS as { key: string }[]).some((f) => f.key === key)) {
      const av = (a as any)[key] || 0, bv = (b as any)[key] || 0;
      return factor * (av - bv);
    }
    // 名簿から追加した列（文字列として比較、数値も自然順で扱う）
    const av = joinRosterValue(roster, key, a.name);
    const bv = joinRosterValue(roster, key, b.name);
    return factor * av.localeCompare(bv, "ja", { numeric: true });
  });
}

function filterAggRows(rows: AggRow[], filters: Record<string, string>, roster: RosterData): AggRow[] {
  const active = Object.entries(filters).filter(([, v]) => v !== "");
  if (!active.length) return rows;
  return rows.filter((r) => active.every(([colId, val]) => joinRosterValue(roster, colId, r.name) === val));
}

function buildCSV(match: MatchData, sortMode: "reg" | "number"): string {
  const headers = ["背番号", "名前", "タッチ数", "スローミス", "キャッチミス", "ブロック", "ゴール", "アシスト", "パス成功率"];
  const players = sortPlayers(match.players, sortMode);
  const rows = players.map((p) => [
    p.number || "", p.name || "", p.touch || 0, p.throwMiss || 0, p.catchMiss || 0,
    p.block || 0, p.goal || 0, p.assist || 0, fmtRate(passRate(p)),
  ]);
  const lines = [headers, ...rows].map((r) => r.map(csvEscape).join(","));
  return "\uFEFF" + lines.join("\r\n");
}

function buildCSVAll(rows: AggRow[]): string {
  const headers = ["背番号", "名前", "試合数", "タッチ数", "スローミス", "キャッチミス", "ブロック", "ゴール", "アシスト", "パス成功率"];
  const body = rows.map((p) => [
    p.number || "", p.name || "", p.games || 0, p.touch || 0, p.throwMiss || 0, p.catchMiss || 0,
    p.block || 0, p.goal || 0, p.assist || 0, fmtRate(passRate(p)),
  ]);
  const lines = [headers, ...body].map((r) => r.map(csvEscape).join(","));
  return "\uFEFF" + lines.join("\r\n");
}

// ---------------- Main component ----------------

export default function App() {
  const [state, setState] = useState<AppState>(loadState);
  const [lastSavedAt, setLastSavedAt] = useState<number | null>(null);
  const [saveError, setSaveError] = useState(false);
  const [undoStack, setUndoStack] = useState<LastAction[]>([]);
  const [toast, setToast] = useState<string | null>(null);
  const toastTimer = useRef<ReturnType<typeof setTimeout> | null>(null);
  const headerRef = useRef<HTMLElement | null>(null);
  const [hdrH, setHdrH] = useState(0);

  const [ui, setUi] = useState<UIState>({
    addPlayerOpen: false,
    newMatchOpen: false,
    newTournamentOpen: false,
    renamingMatch: false,
    renamingTournament: false,
    editingPlayerId: null,
    confirmDeleteMatch: null,
    confirmDeleteTournament: null,
    confirmDeletePlayer: null,
    copyOpen: false,
    copySourceKey: null,
    copySelected: {},
    filterOpen: false,
    filterDraft: {},
    filterLoadedGroupId: null,
    savingGroupNameOpen: false,
    confirmDeleteGroup: null,
    addingRosterColumn: false,
    aggSortKey: null,
    aggSortDir: "desc",
    aggExtraColumnIds: [],
    aggColumnFilters: {},
    addingAward: false,
    helpOpen: false,
    rosterCsvFile: null,
    fullCsvFile: null,
    rosterPickOpen: false,
    rosterPickSelected: {},
  });
  const patchUi = (patch: Partial<UIState>) => setUi((u) => ({ ...u, ...patch }));

  // ---- persistence ----
  useEffect(() => {
    try {
      window.localStorage.setItem(STORAGE_KEY, JSON.stringify(state));
      setLastSavedAt(Date.now());
      setSaveError(false);
    } catch (e) {
      setSaveError(true);
    }
  }, [state]);

  // ---- measure header height for sticky table head offset ----
  useEffect(() => {
    if (headerRef.current) setHdrH(headerRef.current.getBoundingClientRect().height);
  });

  const showToast = useCallback((msg: string) => {
    setToast(msg);
    if (toastTimer.current) clearTimeout(toastTimer.current);
    toastTimer.current = setTimeout(() => setToast(null), 1800);
  }, []);

  // ---- derived accessors ----
  const activeTournament = (): TournamentData =>
    state.tournaments.find((t) => t.id === state.activeTournamentId) || state.tournaments[0];
  const t = activeTournament();
  const activeMatch = (): MatchData => t.matches.find((m) => m.id === t.activeMatchId) || t.matches[0];
  const isRosterView = t.activeMatchId === ROSTER_ID;
  const isSettingsView = t.activeMatchId === SETTINGS_ID;
  const isAllView = !isRosterView && !isSettingsView && (t.activeMatchId === ALL_ID || t.matches.length === 0);
  const match = !isAllView && !isRosterView && !isSettingsView ? activeMatch() : null;

  const updateState = (fn: (draft: AppState) => void) =>
    setState((s) => {
      const next: AppState = structuredClone(s);
      fn(next);
      return next;
    });

  const withActive = (s: AppState) => {
    const tt = s.tournaments.find((x) => x.id === s.activeTournamentId) || s.tournaments[0];
    const mm = tt.matches.find((x) => x.id === tt.activeMatchId) || tt.matches[0];
    return { tt, mm };
  };

  // ---- stat mutations ----
  const MAX_UNDO = 10;

  const bump = (playerId: string, field: StatKey, delta: number) => {
    if (!match) return;
    const matchId = match.id;
    updateState((s) => {
      const { tt } = withActive(s);
      const mm = tt.matches.find((x) => x.id === matchId);
      if (!mm) return;
      const p = mm.players.find((x) => x.id === playerId);
      if (!p) return;
      const current = p[field] || 0;
      const next = Math.max(0, current + delta);
      if (next === current) return;
      p[field] = next;
      setUndoStack((stack) => {
        const nextStack = [...stack, { matchId: mm.id, playerId, field, delta: next - current }];
        return nextStack.length > MAX_UNDO ? nextStack.slice(nextStack.length - MAX_UNDO) : nextStack;
      });
    });
  };

  const undo = () => {
    if (!undoStack.length) return;
    const last = undoStack[undoStack.length - 1];
    updateState((s) => {
      for (const tt of s.tournaments) {
        const mm = tt.matches.find((x) => x.id === last.matchId);
        if (mm) {
          const p = mm.players.find((x) => x.id === last.playerId);
          if (p) p[last.field] = Math.max(0, (p[last.field] || 0) - last.delta);
        }
      }
    });
    setUndoStack((stack) => stack.slice(0, -1));
  };

  // ---- player mutations ----
  const addPlayer = (name: string, number: string) => {
    if (!name || !name.trim()) return;
    updateState((s) => {
      const { mm } = withActive(s);
      mm.players.push({ id: uid(), name: name.trim(), number: (number || "").trim(), ...blankPlayerStats() });
    });
    patchUi({ addPlayerOpen: false });
  };

  const updatePlayer = (id: string, name: string, number: string) => {
    updateState((s) => {
      const { mm } = withActive(s);
      const p = mm.players.find((x) => x.id === id);
      if (!p) return;
      if (name && name.trim()) p.name = name.trim();
      p.number = (number || "").trim();
    });
    patchUi({ editingPlayerId: null });
  };

  const deletePlayer = (id: string) => {
    updateState((s) => {
      const { mm } = withActive(s);
      mm.players = mm.players.filter((x) => x.id !== id);
    });
    patchUi({ confirmDeletePlayer: null });
  };

  // ---- match mutations ----
  const addMatch = (name: string) => {
    updateState((s) => {
      const { tt } = withActive(s);
      const mm = defaultMatch(name && name.trim() ? name.trim() : undefined);
      tt.matches.push(mm);
      tt.activeMatchId = mm.id;
    });
    patchUi({ newMatchOpen: false });
  };

  const renameMatch = (name: string) => {
    if (!name || !name.trim()) { patchUi({ renamingMatch: false }); return; }
    updateState((s) => {
      const { tt } = withActive(s);
      const mm = tt.matches.find((x) => x.id === tt.activeMatchId);
      if (mm) mm.name = name.trim();
    });
    patchUi({ renamingMatch: false });
  };

  const deleteMatch = (id: string) => {
    updateState((s) => {
      const { tt } = withActive(s);
      tt.matches = tt.matches.filter((m) => m.id !== id);
      if (tt.activeMatchId === id) tt.activeMatchId = tt.matches.length ? tt.matches[0].id : ALL_ID;
    });
    patchUi({ confirmDeleteMatch: null });
  };

  const selectMatch = (id: string) => {
    updateState((s) => {
      const { tt } = withActive(s);
      tt.activeMatchId = id;
    });
    patchUi({
      addingRosterColumn: false,
      addPlayerOpen: false, renamingMatch: false, editingPlayerId: null, confirmDeletePlayer: null,
      copyOpen: false, copySourceKey: null, copySelected: {},
      rosterPickOpen: false, rosterPickSelected: {},
      filterOpen: false, filterDraft: {}, filterLoadedGroupId: null, savingGroupNameOpen: false, confirmDeleteGroup: null,
    });
  };

  // ---- filter (lineup) mutations ----
  const applyFilter = (names: string[]) => {
    updateState((s) => {
      const { mm } = withActive(s);
      mm.activeFilterNames = names;
    });
  };
  const clearFilter = () => {
    updateState((s) => {
      const { mm } = withActive(s);
      mm.activeFilterNames = null;
    });
  };

  // ---- tournament mutations ----
  const addTournament = (name: string) => {
    updateState((s) => {
      const tt = defaultTournament(name && name.trim() ? name.trim() : undefined);
      tt.matches = [];
      tt.activeMatchId = ALL_ID;
      s.tournaments.push(tt);
      s.activeTournamentId = tt.id;
    });
    patchUi({ newTournamentOpen: false });
  };

  const renameTournament = (name: string) => {
    if (!name || !name.trim()) { patchUi({ renamingTournament: false }); return; }
    updateState((s) => {
      const tt = s.tournaments.find((x) => x.id === s.activeTournamentId);
      if (tt) tt.name = name.trim();
    });
    patchUi({ renamingTournament: false });
  };

  const deleteTournament = (id: string) => {
    if (state.tournaments.length <= 1) { showToast("最後の大会は削除できません"); patchUi({ confirmDeleteTournament: null }); return; }
    updateState((s) => {
      s.tournaments = s.tournaments.filter((x) => x.id !== id);
      if (s.activeTournamentId === id) s.activeTournamentId = s.tournaments[0].id;
    });
    patchUi({ confirmDeleteTournament: null });
  };

  const selectTournament = (id: string) => {
    updateState((s) => { s.activeTournamentId = id; });
    patchUi({
      addingRosterColumn: false,
      addPlayerOpen: false, renamingMatch: false, renamingTournament: false, editingPlayerId: null,
      confirmDeletePlayer: null, confirmDeleteMatch: null, copyOpen: false, copySourceKey: null, copySelected: {},
      rosterPickOpen: false, rosterPickSelected: {},
      newMatchOpen: false,
      filterOpen: false, filterDraft: {}, filterLoadedGroupId: null, savingGroupNameOpen: false, confirmDeleteGroup: null,
    });
  };

  const setMode = (mode: "add" | "sub") => updateState((s) => { s.mode = mode; });
  const toggleSort = () => updateState((s) => { s.sortMode = s.sortMode === "number" ? "reg" : "number"; });
  const toggleHeaderCollapsed = () => updateState((s) => { s.headerCollapsed = !s.headerCollapsed; });

  // ---- copy players from another match ----
  const allOtherMatches = () => {
    const cur = match;
    const out: { key: string; tournamentName: string; match: MatchData }[] = [];
    state.tournaments.forEach((tt) => {
      tt.matches.forEach((mm) => {
        if (cur && mm.id === cur.id) return;
        if (!mm.players.length) return;
        out.push({ key: `${tt.id}::${mm.id}`, tournamentName: tt.name, match: mm });
      });
    });
    return out;
  };

  const findMatchByKey = (key: string): MatchData | null => {
    const [tid, mid] = String(key).split("::");
    const tt = state.tournaments.find((x) => x.id === tid);
    if (!tt) return null;
    return tt.matches.find((x) => x.id === mid) || null;
  };

  const copyPlayersFrom = (sourceKey: string | null, selected: Record<string, boolean>) => {
    if (!sourceKey) return;
    const source = findMatchByKey(sourceKey);
    if (!source) return;
    let added = 0;
    updateState((s) => {
      const { mm } = withActive(s);
      const existingNames = mm.players.map((p) => p.name.trim());
      source.players.forEach((p) => {
        if (!selected[p.id]) return;
        if (existingNames.includes(p.name.trim())) return;
        mm.players.push({ id: uid(), name: p.name, number: p.number || "", ...blankPlayerStats() });
        existingNames.push(p.name.trim());
        added++;
      });
    });
    patchUi({ copyOpen: false, copySourceKey: null, copySelected: {} });
    showToast(added > 0 ? `${added}人コピーしました` : "追加できる選手がありませんでした（同名の選手は既に登録済みです）");
  };

  // 選手名簿から出場選手を選んで試合に追加する
  const addPlayersFromRoster = (selected: Record<string, boolean>) => {
    let added = 0;
    updateState((s) => {
      const { tt, mm } = withActive(s);
      const existingNames = mm.players.map((p) => p.name.trim());
      tt.roster.rows.forEach((r) => {
        if (!selected[r.id]) return;
        const name = (r.values["name"] || "").trim();
        if (!name) return;
        if (existingNames.includes(name)) return;
        mm.players.push({ id: uid(), name, number: (r.values["number"] || "").trim(), ...blankPlayerStats() });
        existingNames.push(name);
        added++;
      });
    });
    patchUi({ rosterPickOpen: false, rosterPickSelected: {} });
    showToast(added > 0 ? `${added}人追加しました` : "追加できる選手がありませんでした（同名の選手は既に登録済みです、または名前が未入力です）");
  };

  // ---- groups (saved lineups) ----
  const saveGroup = (name: string, memberNames: string[]) => {
    updateState((s) => {
      const tt = s.tournaments.find((x) => x.id === s.activeTournamentId) || s.tournaments[0];
      if (!Array.isArray(tt.groups)) tt.groups = [];
      tt.groups.push({ id: uid(), name, memberNames });
    });
  };
  const updateGroup = (groupId: string, memberNames: string[]) => {
    updateState((s) => {
      const tt = s.tournaments.find((x) => x.id === s.activeTournamentId) || s.tournaments[0];
      const g = (tt.groups || []).find((x) => x.id === groupId);
      if (g) g.memberNames = memberNames;
    });
  };
  const deleteGroup = (groupId: string) => {
    updateState((s) => {
      const tt = s.tournaments.find((x) => x.id === s.activeTournamentId) || s.tournaments[0];
      tt.groups = (tt.groups || []).filter((x) => x.id !== groupId);
    });
    patchUi({ confirmDeleteGroup: null });
  };

  // ---- roster (選手名簿) ----
  const addRosterRow = () => {
    updateState((s) => {
      const tt = s.tournaments.find((x) => x.id === s.activeTournamentId) || s.tournaments[0];
      tt.roster.rows.push({ id: uid(), values: {} });
    });
  };
  const deleteRosterRow = (rowId: string) => {
    updateState((s) => {
      const tt = s.tournaments.find((x) => x.id === s.activeTournamentId) || s.tournaments[0];
      tt.roster.rows = tt.roster.rows.filter((r) => r.id !== rowId);
    });
  };
  const updateRosterCell = (rowId: string, colId: string, value: string) => {
    updateState((s) => {
      const tt = s.tournaments.find((x) => x.id === s.activeTournamentId) || s.tournaments[0];
      const row = tt.roster.rows.find((r) => r.id === rowId);
      if (row) row.values[colId] = value;
    });
  };
  const addRosterColumn = (name: string) => {
    if (!name || !name.trim()) return;
    updateState((s) => {
      const tt = s.tournaments.find((x) => x.id === s.activeTournamentId) || s.tournaments[0];
      tt.roster.columns.push({ id: uid(), name: name.trim() });
    });
    patchUi({ addingRosterColumn: false });
  };
  const renameRosterColumn = (colId: string, name: string) => {
    updateState((s) => {
      const tt = s.tournaments.find((x) => x.id === s.activeTournamentId) || s.tournaments[0];
      const col = tt.roster.columns.find((c) => c.id === colId);
      if (col && !col.locked && name.trim()) col.name = name.trim();
    });
  };
  const deleteRosterColumn = (colId: string) => {
    updateState((s) => {
      const tt = s.tournaments.find((x) => x.id === s.activeTournamentId) || s.tournaments[0];
      const col = tt.roster.columns.find((c) => c.id === colId);
      if (!col || col.locked) return;
      tt.roster.columns = tt.roster.columns.filter((c) => c.id !== colId);
      tt.roster.rows.forEach((r) => { delete r.values[colId]; });
    });
  };
  const copyRosterToClipboard = (roster: RosterData) => {
    const headerLine = roster.columns.map((c) => c.name).join("\t");
    const bodyLines = roster.rows.map((r) => roster.columns.map((c) => (r.values[c.id] || "")).join("\t"));
    const text = [headerLine, ...bodyLines].join("\n");
    if (navigator.clipboard && navigator.clipboard.writeText) {
      navigator.clipboard.writeText(text).then(
        () => showToast("コピーしました。表計算ソフトに貼り付けできます"),
        () => showToast("コピーできませんでした")
      );
    } else {
      showToast("この環境ではコピーできません");
    }
  };

  const exportRosterCSV = (roster: RosterData, tournamentName: string) => {
    if (!roster.rows.length) { showToast("名簿に選手がいません"); return; }
    const headers = roster.columns.map((c) => c.name);
    const bodyRows = roster.rows.map((r) => roster.columns.map((c) => r.values[c.id] || ""));
    const csv = "\uFEFF" + [headers, ...bodyRows].map((r) => r.map(csvEscape).join(",")).join("\r\n");
    downloadTextFile(csv, `${sanitizeFilename(tournamentName)}_選手名簿.csv`, "text/csv;charset=utf-8;");
    showToast("CSVを保存しました");
  };

  // 名簿CSVの取り込み：1列目→背番号、2列目→名前（ヘッダー文言は問わない）。
  // 先頭行がヘッダーらしければ、3列目以降はヘッダー名で既存の列と突き合わせ、なければ新しい列を作る。
  // ヘッダーが無ければ、3列目以降は既存の列に順番どおり取り込む（足りなければ新しい列を作る）。
  const importRosterCSV = (file: File) => {
    const reader = new FileReader();
    reader.onload = () => {
      const text = String(reader.result || "");
      const lines = text.split(/\r\n|\n|\r/).filter((l) => l.trim().length > 0);
      if (!lines.length) { showToast("読み取れる行がありませんでした"); return; }
      const grid = lines.map(parseCSVLine);
      const hasHeader = isLikelyHeaderCell(grid[0][0] || "");
      const headerRow = hasHeader ? grid[0] : null;
      const dataRows = hasHeader ? grid.slice(1) : grid;
      let added = 0, updated = 0;
      updateState((s) => {
        const tt = s.tournaments.find((x) => x.id === s.activeTournamentId) || s.tournaments[0];
        const colIdByName: Record<string, string> = {};
        tt.roster.columns.forEach((c) => { if (!c.locked) colIdByName[c.name] = c.id; });
        if (headerRow) {
          headerRow.slice(2).forEach((h) => {
            const name = (h || "").trim();
            if (!name || colIdByName[name]) return;
            const newCol: RosterColumn = { id: uid(), name };
            tt.roster.columns.push(newCol);
            colIdByName[name] = newCol.id;
          });
        }
        dataRows.forEach((cells) => {
          const number = (cells[0] || "").trim();
          const name = (cells[1] || "").trim();
          if (!name) return;
          let target = tt.roster.rows.find((r) => (r.values["name"] || "").trim() === name);
          if (!target) { target = { id: uid(), values: {} }; tt.roster.rows.push(target); added++; }
          else updated++;
          target.values["number"] = number;
          target.values["name"] = name;
          if (headerRow) {
            headerRow.slice(2).forEach((h, i) => {
              const hn = (h || "").trim();
              if (!hn) return;
              const v = cells[i + 2];
              if (v !== undefined) target!.values[colIdByName[hn]] = v.trim();
            });
          } else {
            const nonLocked = tt.roster.columns.filter((c) => !c.locked);
            for (let i = 2; i < cells.length; i++) {
              const posIndex = i - 2;
              let col = nonLocked[posIndex];
              if (!col) {
                col = { id: uid(), name: `列${posIndex + 1}` };
                tt.roster.columns.push(col);
                nonLocked.push(col);
              }
              target!.values[col.id] = (cells[i] || "").trim();
            }
          }
        });
      });
      showToast(`${added}人追加、${updated}人更新しました`);
      patchUi({ rosterCsvFile: null });
    };
    reader.onerror = () => showToast("ファイルを読み込めませんでした");
    reader.readAsText(file, "utf-8");
  };

  // 表計算ソフトからのコピー＆ペースト（タブ区切り）を、貼り付け先のセルを起点に複数セルへ展開する
  const pasteRosterGrid = (anchorRow: number, anchorCol: number, grid: string[][]) => {
    if (!grid.length) return;
    const topLeftHeader = anchorRow === 0 && anchorCol === 0 && isLikelyHeaderCell(grid[0][0] || "");
    const headerRow = topLeftHeader ? grid[0] : null;
    const dataGrid = topLeftHeader ? grid.slice(1) : grid;
    updateState((s) => {
      const tt = s.tournaments.find((x) => x.id === s.activeTournamentId) || s.tournaments[0];
      const colIdByName: Record<string, string> = {};
      tt.roster.columns.forEach((c) => { if (!c.locked) colIdByName[c.name] = c.id; });
      if (headerRow) {
        headerRow.slice(2).forEach((h) => {
          const name = (h || "").trim();
          if (!name || colIdByName[name]) return;
          const newCol: RosterColumn = { id: uid(), name };
          tt.roster.columns.push(newCol);
          colIdByName[name] = newCol.id;
        });
      }
      dataGrid.forEach((rowCells, r) => {
        const targetRowIndex = anchorRow + r;
        while (tt.roster.rows.length <= targetRowIndex) tt.roster.rows.push({ id: uid(), values: {} });
        const targetRow = tt.roster.rows[targetRowIndex];
        rowCells.forEach((cellVal, c) => {
          const targetColIndex = anchorCol + c;
          const v = (cellVal || "").trim();
          if (targetColIndex === 0) { targetRow.values["number"] = v; return; }
          if (targetColIndex === 1) { targetRow.values["name"] = v; return; }
          if (headerRow) {
            const hn = (headerRow[targetColIndex] || "").trim();
            if (!hn) return;
            const colId = colIdByName[hn];
            if (colId) targetRow.values[colId] = v;
          } else {
            const nonLocked = tt.roster.columns.filter((c2) => !c2.locked);
            const posIndex = targetColIndex - 2;
            let col = nonLocked[posIndex];
            if (!col) {
              col = { id: uid(), name: `列${posIndex + 1}` };
              tt.roster.columns.push(col);
            }
            targetRow.values[col.id] = v;
          }
        });
      });
    });
    showToast("貼り付けました");
  };

  // ---- man of the match ----
  const toggleMom = (playerId: string) => {
    if (!match) return;
    const matchId = match.id;
    updateState((s) => {
      const { tt } = withActive(s);
      const mm = tt.matches.find((x) => x.id === matchId);
      if (!mm) return;
      const target = mm.players.find((p) => p.id === playerId);
      if (!target) return;
      const turningOn = !target.mom;
      mm.players.forEach((p) => { p.mom = false; });
      if (turningOn) target.mom = true;
    });
  };

  // ---- tournament awards (個人賞) ----
  const setAwardWinner = (awardId: string, playerName: string) => {
    updateState((s) => {
      const tt = s.tournaments.find((x) => x.id === s.activeTournamentId) || s.tournaments[0];
      const a = tt.awards.find((x) => x.id === awardId);
      if (a) a.playerName = playerName;
    });
  };
  const addAward = (name: string) => {
    if (!name || !name.trim()) return;
    updateState((s) => {
      const tt = s.tournaments.find((x) => x.id === s.activeTournamentId) || s.tournaments[0];
      tt.awards.push({ id: uid(), name: name.trim(), playerName: "" });
    });
    patchUi({ addingAward: false });
  };
  const renameAward = (awardId: string, name: string) => {
    if (!name.trim()) return;
    updateState((s) => {
      const tt = s.tournaments.find((x) => x.id === s.activeTournamentId) || s.tournaments[0];
      const a = tt.awards.find((x) => x.id === awardId);
      if (a) a.name = name.trim();
    });
  };
  const deleteAward = (awardId: string) => {
    updateState((s) => {
      const tt = s.tournaments.find((x) => x.id === s.activeTournamentId) || s.tournaments[0];
      tt.awards = tt.awards.filter((x) => x.id !== awardId);
    });
  };

  // ---- theme color ----
  const setThemeColor = (color: string | undefined) => updateState((s) => { s.themeColor = color; });

  // ---- full data backup (全大会・全試合一括CSV) ----
  const exportAllDataCSV = () => {
    const headers = ["大会名", "試合名", "背番号", "名前", "タッチ数", "スローミス", "キャッチミス", "ブロック", "ゴール", "アシスト", "パス成功率", "MOM"];
    const rows: string[][] = [];
    state.tournaments.forEach((tt) => {
      tt.matches.forEach((mm) => {
        mm.players.forEach((p) => {
          rows.push([
            tt.name, mm.name, p.number || "", p.name || "",
            String(p.touch || 0), String(p.throwMiss || 0), String(p.catchMiss || 0),
            String(p.block || 0), String(p.goal || 0), String(p.assist || 0),
            fmtRate(passRate(p)), p.mom ? "○" : "",
          ]);
        });
      });
    });
    if (!rows.length) { showToast("書き出せるデータがありません"); return; }
    const csv = "\uFEFF" + [headers, ...rows].map((r) => r.map(csvEscape).join(",")).join("\r\n");
    downloadTextFile(csv, "全大会_全試合データ.csv", "text/csv;charset=utf-8;");
    showToast("CSVを保存しました");
  };

  // 大会名・試合名・選手名で既存データを探し、無ければ作成しつつスタッツを上書き取り込みする
  const importAllDataCSV = (file: File) => {
    const reader = new FileReader();
    reader.onload = () => {
      const { rows } = parseCSVWithHeader(String(reader.result || ""));
      if (!rows.length) { showToast("読み取れる行がありませんでした"); return; }
      let tCount = 0, mCount = 0, pCount = 0;
      updateState((s) => {
        rows.forEach((row) => {
          const tournamentName = (row["大会名"] || "").trim();
          const matchName = (row["試合名"] || "").trim();
          const playerName = (row["名前"] || "").trim();
          if (!tournamentName || !matchName || !playerName) return;
          let tt = s.tournaments.find((x) => x.name === tournamentName);
          if (!tt) {
            tt = defaultTournament(tournamentName);
            tt.matches = [];
            s.tournaments.push(tt);
            tCount++;
          }
          let mm = tt.matches.find((x) => x.name === matchName);
          if (!mm) {
            mm = defaultMatch(matchName);
            tt.matches.push(mm);
            mCount++;
          }
          let p = mm.players.find((x) => x.name.trim() === playerName);
          if (!p) {
            p = { id: uid(), name: playerName, number: "", ...blankPlayerStats() };
            mm.players.push(p);
            pCount++;
          }
          p.number = (row["背番号"] || p.number || "").trim();
          p.touch = parseInt(row["タッチ数"] || "0", 10) || 0;
          p.throwMiss = parseInt(row["スローミス"] || "0", 10) || 0;
          p.catchMiss = parseInt(row["キャッチミス"] || "0", 10) || 0;
          p.block = parseInt(row["ブロック"] || "0", 10) || 0;
          p.goal = parseInt(row["ゴール"] || "0", 10) || 0;
          p.assist = parseInt(row["アシスト"] || "0", 10) || 0;
          if (row["MOM"] !== undefined) {
            if (truthyFlag(row["MOM"])) {
              mm.players.forEach((pl) => { pl.mom = false; });
              p.mom = true;
            }
          }
        });
      });
      showToast(`大会${tCount}件・試合${mCount}件・選手記録${pCount}件を取り込みました`);
      patchUi({ fullCsvFile: null });
    };
    reader.onerror = () => showToast("ファイルを読み込めませんでした");
    reader.readAsText(file, "utf-8");
  };

  // ---- CSV / PDF ----
  const exportCSV = () => {
    if (isAllView) {
      const rows = aggregateTournament(t, state.sortMode);
      if (!rows.length) { showToast("まだ記録がありません"); return; }
      downloadTextFile(buildCSVAll(rows), `${sanitizeFilename(t.name)}_大会集計.csv`, "text/csv;charset=utf-8;");
    } else if (match) {
      if (!match.players.length) { showToast("選手を追加してから書き出してください"); return; }
      downloadTextFile(buildCSV(match, state.sortMode), `${sanitizeFilename(match.name)}.csv`, "text/csv;charset=utf-8;");
    }
    showToast("CSVを保存しました");
  };

  const printPage = () => {
    const hasData = isAllView ? aggregateTournament(t, state.sortMode).length > 0 : !!match && match.players.length > 0;
    if (!hasData) { showToast("まだ記録がありません"); return; }
    window.print();
  };

  // ---- render helpers ----
  const rawPlayers = match ? match.players : [];
  const filterActive = !!(match && match.activeFilterNames && match.activeFilterNames.length);
  const displayPlayers = filterActive && match
    ? rawPlayers.filter((p) => (match.activeFilterNames as string[]).includes(p.name.trim()))
    : rawPlayers;
  const players = sortPlayers(displayPlayers, state.sortMode);
  const aggRows = isAllView ? aggregateTournament(t, state.sortMode) : [];

  const now = new Date();
  const printStamp = `${now.getFullYear()}/${now.getMonth() + 1}/${now.getDate()} ${pad2(now.getHours())}:${pad2(now.getMinutes())}`;

  return (
    <div className="usa-root" style={{ ["--usa-pitch" as any]: state.themeColor || DEFAULT_PITCH, ["--usa-pitch-deep" as any]: shadeColor(state.themeColor || DEFAULT_PITCH, -0.35) }}>
      <style>{CSS}</style>
      <div className="usa-app">
        <header className="usa-hdr" ref={headerRef}>
          <div className="usa-hdr-top">
            <span className="usa-brand">🥏 アルティメット スタッツ</span>
            <div className="usa-hdr-top-right">
              <span className={"usa-save-status" + (saveError ? " err" : lastSavedAt ? " ok" : "")}>
                {saveError ? "⚠️ 自動保存できません" : lastSavedAt ? `● 自動保存 ${pad2(new Date(lastSavedAt).getHours())}:${pad2(new Date(lastSavedAt).getMinutes())}` : "自動保存 待機中"}
              </span>
              <button className="usa-collapse-btn" title="使い方" onClick={() => patchUi({ helpOpen: true })}>？</button>
              <button className="usa-collapse-btn" onClick={toggleHeaderCollapsed}>
                {state.headerCollapsed ? "▾ 展開" : "▴ 折りたたむ"}
              </button>
            </div>
          </div>

          {state.headerCollapsed ? (
            <div className="usa-hdr-summary" onClick={toggleHeaderCollapsed}>
              <span className="ctx"><img className="icon-img" src={TROPHY_ICON} alt="" /> {t.name} ▸ {isSettingsView ? "⚙️ 設定" : isRosterView ? "📋 選手名簿" : isAllView ? <><img className="icon-img" src={AGG_ICON} alt="" /> 大会全体の集計</> : match!.name}</span>
              <span className="hint">タップで展開 ▾</span>
            </div>
          ) : (
            <>
              <div className="usa-tabs">
                {state.tournaments.map((tt) => (
                  ui.confirmDeleteTournament === tt.id ? (
                    <div key={tt.id} className="usa-tab tourney active" style={{ background: "var(--usa-miss)", color: "#fff" }}>
                      <span>削除する？</span>
                      <button className="x" style={{ opacity: 1 }} onClick={() => deleteTournament(tt.id)}>✔</button>
                      <button className="x" onClick={() => patchUi({ confirmDeleteTournament: null })}>✕</button>
                    </div>
                  ) : (
                    <div key={tt.id} className={"usa-tab tourney" + (tt.id === t.id ? " active" : "")} onClick={() => selectTournament(tt.id)}>
                      <span><img className="icon-img" src={TROPHY_ICON} alt="" /> {tt.name}</span>
                      {state.tournaments.length > 1 && (
                        <button className="x" onClick={(e) => { e.stopPropagation(); patchUi({ confirmDeleteTournament: tt.id }); }}>✕</button>
                      )}
                    </div>
                  )
                ))}
                {ui.newTournamentOpen ? (
                  <NewTabForm placeholder={`${todayLabel()} 大会`} onConfirm={addTournament} onCancel={() => patchUi({ newTournamentOpen: false })} light />
                ) : (
                  <button className="usa-tab-new" onClick={() => patchUi({ newTournamentOpen: true })}>＋ 新しい大会</button>
                )}
              </div>

              <div className="usa-hdr-bottom tourney-row">
                {ui.renamingTournament ? (
                  <RenameForm value={t.name} onConfirm={renameTournament} onCancel={() => patchUi({ renamingTournament: false })} />
                ) : (
                  <>
                    <div className="usa-match-title tourney">{t.name} · {t.matches.length}試合</div>
                    <button className="usa-icon-btn" title="大会名を編集" onClick={() => patchUi({ renamingTournament: true })}>✎</button>
                  </>
                )}
              </div>

              <div className="usa-tabs">
                <div className={"usa-tab pinned" + (isAllView ? " active" : "")} onClick={() => selectMatch(ALL_ID)}>
                  <span><img className="icon-img" src={AGG_ICON} alt="" /> 大会全体の集計</span>
                </div>
                <div className={"usa-tab pinned" + (isRosterView ? " active" : "")} onClick={() => selectMatch(ROSTER_ID)}>
                  <span>📋 選手名簿</span>
                </div>
                <div className={"usa-tab pinned" + (isSettingsView ? " active" : "")} onClick={() => selectMatch(SETTINGS_ID)}>
                  <span>⚙️ 設定</span>
                </div>
                <div className="usa-tab-sep" />
                {t.matches.map((mm) => (
                  ui.confirmDeleteMatch === mm.id ? (
                    <div key={mm.id} className="usa-tab active" style={{ background: "var(--usa-miss)", color: "#fff" }}>
                      <span>削除する？</span>
                      <button className="x" style={{ opacity: 1 }} onClick={() => deleteMatch(mm.id)}>✔</button>
                      <button className="x" onClick={() => patchUi({ confirmDeleteMatch: null })}>✕</button>
                    </div>
                  ) : (
                    <div key={mm.id} className={"usa-tab" + (!isAllView && mm.id === t.activeMatchId ? " active" : "")} onClick={() => selectMatch(mm.id)}>
                      <span>{mm.name}</span>
                      <button className="x" onClick={(e) => { e.stopPropagation(); patchUi({ confirmDeleteMatch: mm.id }); }}>✕</button>
                    </div>
                  )
                ))}
                {ui.newMatchOpen ? (
                  <NewTabForm placeholder={`${todayLabel()} 試合`} onConfirm={addMatch} onCancel={() => patchUi({ newMatchOpen: false })} />
                ) : (
                  <button className="usa-tab-new" onClick={() => patchUi({ newMatchOpen: true })}>＋ 新しい試合</button>
                )}
              </div>

              <div className="usa-hdr-bottom">
                {isSettingsView ? (
                  <div className="usa-match-title">⚙️ 設定</div>
                ) : isRosterView ? (
                  <div className="usa-match-title">📋 選手名簿 · {t.roster.rows.length}人</div>
                ) : isAllView ? (
                  <>
                    <div className="usa-match-title"><img className="icon-img" src={AGG_ICON} alt="" /> 大会全体の集計 · {aggRows.length}人 · 全{t.matches.length}試合</div>
                    <SortButton sortMode={state.sortMode} onClick={toggleSort} />
                  </>
                ) : ui.renamingMatch ? (
                  <RenameForm value={match!.name} onConfirm={renameMatch} onCancel={() => patchUi({ renamingMatch: false })} />
                ) : (
                  <>
                    <div className="usa-match-title">{match!.name} · {match!.players.length}人</div>
                    <SortButton sortMode={state.sortMode} onClick={toggleSort} />
                    <button className="usa-icon-btn" title="試合名を編集" onClick={() => patchUi({ renamingMatch: true })}>✎</button>
                  </>
                )}
              </div>
            </>
          )}
        </header>

        <div className="usa-print-title">
          <div className="t1">🥏 {t.name} ▸ {isSettingsView ? "設定" : isRosterView ? "選手名簿" : isAllView ? "大会全体の集計" : match!.name}</div>
          <div className="t2">出力日時: {printStamp}</div>
        </div>

        <main className="usa-main" style={{ ["--usa-hdr-h" as any]: `${hdrH}px` }}>
          {isSettingsView ? (
            <SettingsView
              state={state} t={t} ui={ui} patchUi={patchUi}
              setThemeColor={setThemeColor}
              exportRosterCSV={exportRosterCSV} importRosterCSV={importRosterCSV}
              exportAllDataCSV={exportAllDataCSV} importAllDataCSV={importAllDataCSV}
            />
          ) : isRosterView ? (
            <RosterView
              roster={t.roster} ui={ui} patchUi={patchUi}
              deleteRosterRow={deleteRosterRow} updateRosterCell={updateRosterCell}
              addRosterColumn={addRosterColumn} renameRosterColumn={renameRosterColumn} deleteRosterColumn={deleteRosterColumn}
              importRosterCSV={importRosterCSV} pasteRosterGrid={pasteRosterGrid}
            />
          ) : isAllView ? (
            <AggregateView
              aggRows={aggRows} roster={t.roster} awards={t.awards} ui={ui} patchUi={patchUi}
              setAwardWinner={setAwardWinner} addAward={addAward} renameAward={renameAward} deleteAward={deleteAward}
            />
          ) : match!.players.length === 0 ? (
            <>
              <div className="usa-empty">
                <span className="disc">🥏</span>まだ選手がいません。<br />選手を追加して、セルをタップしてスタッツを記録しましょう。
              </div>
              <AddPlayerArea
                ui={ui} patchUi={patchUi} addPlayer={addPlayer} allOtherMatches={allOtherMatches}
                copyPlayersFrom={copyPlayersFrom} findMatchByKey={findMatchByKey}
                roster={t.roster} addPlayersFromRoster={addPlayersFromRoster}
              />
            </>
          ) : (
            <>
              {match!.players.length > 0 && (
                <FilterBar
                  match={match!} t={t} ui={ui} patchUi={patchUi}
                  applyFilter={applyFilter} clearFilter={clearFilter}
                  saveGroup={saveGroup} updateGroup={updateGroup} deleteGroup={deleteGroup}
                  showToast={showToast}
                />
              )}
              {players.length === 0 ? (
                <div className="usa-empty">フィルタ条件に一致する選手がいません。</div>
              ) : (
                <div className="usa-table-wrap">
                  <table className="usa-stats">
                    <thead>
                      <tr>
                        <th className="sticky-no">NO</th>
                        <th className="sticky-name">選手</th>
                        {FIELDS.map((f) => <th key={f.key} className={f.kind === "miss" ? "miss-col" : f.kind === "good" ? "good-col" : ""}>{f.label}</th>)}
                        <th>パス成功率</th>
                      </tr>
                    </thead>
                    <tbody>
                      {players.map((p) => (
                        <PlayerRow
                          key={p.id} p={p} ui={ui} patchUi={patchUi}
                          bump={bump} mode={state.mode}
                          updatePlayer={updatePlayer} deletePlayer={deletePlayer} toggleMom={toggleMom}
                        />
                      ))}
                    </tbody>
                    <tfoot>
                      <TotalsRow players={players} />
                    </tfoot>
                  </table>
                </div>
              )}
              <AddPlayerArea
                ui={ui} patchUi={patchUi} addPlayer={addPlayer} allOtherMatches={allOtherMatches}
                copyPlayersFrom={copyPlayersFrom} findMatchByKey={findMatchByKey}
                roster={t.roster} addPlayersFromRoster={addPlayersFromRoster}
              />
            </>
          )}
        </main>

        <footer className="usa-toolbar">
          {isSettingsView ? (
            <span style={{ fontSize: 12, color: "var(--usa-ink-soft)" }}>設定は自動的に保存されます</span>
          ) : isRosterView ? (
            <>
              <button className="usa-tool-btn" onClick={addRosterRow}>＋ 行を追加</button>
              <button className="usa-tool-btn primary" onClick={() => copyRosterToClipboard(t.roster)}>📋 コピー</button>
            </>
          ) : isAllView ? (
            <>
              <button className="usa-tool-btn" onClick={printPage}>PDF書き出し</button>
              <button className="usa-tool-btn primary" onClick={exportCSV}>CSV書き出し</button>
            </>
          ) : (
            <>
              <div className="usa-mode-toggle">
                <button className={state.mode === "add" ? "active" : ""} onClick={() => setMode("add")}>＋1</button>
                <button className={state.mode === "sub" ? "active" : ""} onClick={() => setMode("sub")}>－1</button>
              </div>
              <button className="usa-tool-btn" disabled={undoStack.length === 0} onClick={undo} title="直近の操作を1つずつ元に戻します（最大10件）">
                元に戻す{undoStack.length > 0 ? ` (${undoStack.length})` : ""}
              </button>
              <button className="usa-tool-btn" onClick={printPage}>PDF</button>
              <button className="usa-tool-btn primary" onClick={exportCSV}>CSV書き出し</button>
            </>
          )}
        </footer>
      </div>

      {toast && <div className="usa-toast-root"><div className="usa-toast show">{toast}</div></div>}
      {ui.helpOpen && <HelpModal onClose={() => patchUi({ helpOpen: false })} />}
    </div>
  );
}

// ---------------- small subcomponents ----------------

function SortButton({ sortMode, onClick }: { sortMode: "reg" | "number"; onClick: () => void }) {
  return (
    <button className={"usa-icon-btn" + (sortMode === "number" ? " active" : "")} title={sortMode === "number" ? "背番号順（タップで登録順に）" : "登録順（タップで背番号順に）"} onClick={onClick}>
      {sortMode === "number" ? "🔢" : "☰"}
    </button>
  );
}

function NewTabForm({ placeholder, onConfirm, onCancel, light }: { placeholder: string; onConfirm: (v: string) => void; onCancel: () => void; light?: boolean }) {
  const [val, setVal] = useState("");
  return (
    <div className={"usa-tab active" + (light ? " tourney" : "")} style={{ display: "flex", gap: 6 }}>
      <input
        autoFocus value={val} placeholder={placeholder}
        onChange={(e) => setVal(e.target.value)}
        onKeyDown={(e) => { if (e.key === "Enter") onConfirm(val); }}
        style={{ border: "none", background: "transparent", color: light ? "var(--usa-pitch-deep)" : "var(--usa-disc-ink)", fontWeight: 700, width: 120, fontFamily: "inherit", fontSize: 13 }}
      />
      <button className="x" style={{ opacity: 1 }} onClick={() => onConfirm(val)}>✔</button>
      <button className="x" onClick={onCancel}>✕</button>
    </div>
  );
}

function RenameForm({ value, onConfirm, onCancel }: { value: string; onConfirm: (v: string) => void; onCancel: () => void }) {
  const [val, setVal] = useState(value);
  return (
    <>
      <div className="usa-match-title">
        <input autoFocus value={val} onChange={(e) => setVal(e.target.value)} onKeyDown={(e) => { if (e.key === "Enter") onConfirm(val); }} />
      </div>
      <button className="usa-icon-btn" onClick={() => onConfirm(val)}>✔</button>
      <button className="usa-icon-btn" onClick={onCancel}>✕</button>
    </>
  );
}

// ---- aggregate (大会全体の集計) view ----

function AggregateView({ aggRows, roster, awards, ui, patchUi, setAwardWinner, addAward, renameAward, deleteAward }: {
  aggRows: AggRow[]; roster: RosterData; awards: TournamentAward[]; ui: UIState; patchUi: (patch: Partial<UIState>) => void;
  setAwardWinner: (awardId: string, playerName: string) => void;
  addAward: (name: string) => void; renameAward: (awardId: string, name: string) => void; deleteAward: (awardId: string) => void;
}) {
  if (aggRows.length === 0) {
    return (
      <div className="usa-empty">
        <img className="icon-img-lg" src={AGG_ICON} alt="" />
        この大会にはまだ試合がありません。<br />「＋ 新しい試合」で試合を追加して、スタッツを記録しましょう。
        <div><button className="usa-btn primary" onClick={() => patchUi({ newMatchOpen: true })}>＋ 試合を追加</button></div>
      </div>
    );
  }

  const extraCols = roster.columns.filter((c) => !c.locked);
  const activeExtraCols = extraCols.filter((c) => ui.aggExtraColumnIds.includes(c.id));

  const toggleExtraColumn = (colId: string) => {
    const on = ui.aggExtraColumnIds.includes(colId);
    const nextFilters = { ...ui.aggColumnFilters };
    if (on) delete nextFilters[colId];
    patchUi({
      aggExtraColumnIds: on ? ui.aggExtraColumnIds.filter((id) => id !== colId) : [...ui.aggExtraColumnIds, colId],
      aggColumnFilters: nextFilters,
    });
  };

  const toggleSort = (key: string) => {
    if (ui.aggSortKey === key) {
      patchUi({ aggSortDir: ui.aggSortDir === "asc" ? "desc" : "asc" });
    } else {
      const numericDefault = key === "name" || key === "number" || extraCols.some((c) => c.id === key);
      patchUi({ aggSortKey: key, aggSortDir: numericDefault ? "asc" : "desc" });
    }
  };

  const sortArrow = (key: string) => (ui.aggSortKey === key ? (ui.aggSortDir === "asc" ? " ▲" : " ▼") : "");

  const filteredRows = filterAggRows(aggRows, ui.aggColumnFilters, roster);
  const rows = sortAggRows(filteredRows, ui.aggSortKey, ui.aggSortDir, roster);

  return (
    <>
      <div className="usa-panel">
        <div className="usa-panel-title">🏅 個人賞</div>
        <div className="usa-award-list">
          {awards.map((a) => (
            <AwardRow key={a.id} award={a} aggRows={aggRows} onSetWinner={setAwardWinner} onRename={renameAward} onDelete={deleteAward} />
          ))}
        </div>
        {ui.addingAward ? (
          <NewColumnForm onConfirm={addAward} onCancel={() => patchUi({ addingAward: false })} placeholder="賞名" />
        ) : (
          <button className="usa-tool-btn" style={{ padding: "6px 10px", fontSize: 12, marginTop: 6 }} onClick={() => patchUi({ addingAward: true })}>＋ 賞を追加</button>
        )}
        <div className="usa-panel-hint" style={{ marginTop: 8, marginBottom: 0 }}>1人が複数の賞を受賞してもかまいません。</div>
      </div>

      {extraCols.length > 0 ? (
        <div className="usa-filter-bar">
          <span style={{ fontSize: 12, color: "var(--usa-ink-soft)" }}>名簿の列を表示:</span>
          {extraCols.map((c) => (
            <button
              key={c.id}
              className={"usa-group-chip" + (ui.aggExtraColumnIds.includes(c.id) ? " active" : "")}
              style={ui.aggExtraColumnIds.includes(c.id) ? { background: "var(--usa-disc)", color: "var(--usa-disc-ink)", borderRadius: 999, border: "none" } : { borderRadius: 999 }}
              onClick={() => toggleExtraColumn(c.id)}
            >
              {c.name}
            </button>
          ))}
        </div>
      ) : (
        <div className="usa-filter-bar">
          <span style={{ fontSize: 12, color: "var(--usa-ink-soft)" }}>「📋 選手名簿」で列（学年など）を追加すると、ここに表示・絞り込み用の項目として選べるようになります。</span>
        </div>
      )}
      {activeExtraCols.length > 0 && (
        <div className="usa-filter-bar">
          {activeExtraCols.map((c) => {
            const values = Array.from(new Set(aggRows.map((r) => joinRosterValue(roster, c.id, r.name)).filter((v) => v !== ""))).sort((a, b) => a.localeCompare(b, "ja", { numeric: true }));
            return (
              <label key={c.id} style={{ fontSize: 12, display: "flex", alignItems: "center", gap: 4 }}>
                {c.name}:
                <select
                  value={ui.aggColumnFilters[c.id] || ""}
                  onChange={(e) => patchUi({ aggColumnFilters: { ...ui.aggColumnFilters, [c.id]: e.target.value } })}
                  style={{ padding: "4px 6px", borderRadius: 8, border: "1px solid var(--usa-line)", background: "var(--usa-chalk)", color: "var(--usa-ink)", fontSize: 12 }}
                >
                  <option value="">すべて</option>
                  {values.map((v) => <option key={v} value={v}>{v}</option>)}
                </select>
              </label>
            );
          })}
        </div>
      )}
      {rows.length === 0 ? (
        <div className="usa-empty">絞り込み条件に一致する選手がいません。</div>
      ) : (
        <div className="usa-table-wrap">
          <table className="usa-stats">
            <thead>
              <tr>
                <th className="sticky-no" style={{ cursor: "pointer" }} onClick={() => toggleSort("number")}>NO{sortArrow("number")}</th>
                <th className="sticky-name" style={{ cursor: "pointer" }} onClick={() => toggleSort("name")}>選手{sortArrow("name")}</th>
                <th style={{ cursor: "pointer" }} onClick={() => toggleSort("games")}>試合数{sortArrow("games")}</th>
                {activeExtraCols.map((c) => (
                  <th key={c.id} style={{ cursor: "pointer" }} onClick={() => toggleSort(c.id)}>{c.name}{sortArrow(c.id)}</th>
                ))}
                {FIELDS.map((f) => (
                  <th key={f.key} className={f.kind === "miss" ? "miss-col" : f.kind === "good" ? "good-col" : ""} style={{ cursor: "pointer" }} onClick={() => toggleSort(f.key)}>
                    {f.label}{sortArrow(f.key)}
                  </th>
                ))}
                <th style={{ cursor: "pointer" }} onClick={() => toggleSort("passRate")}>パス成功率{sortArrow("passRate")}</th>
              </tr>
            </thead>
            <tbody>
              {rows.map((p, i) => (
                <tr key={i}>
                  <td className="sticky-no">{p.number ? <span className="no-value num">{p.number}</span> : <span className="no-value empty">―</span>}</td>
                  <td className="sticky-name"><div className="usa-player-name">{p.name}</div></td>
                  <td className="num" style={{ textAlign: "center" }}>{p.games}</td>
                  {activeExtraCols.map((c) => (
                    <td key={c.id} style={{ textAlign: "center", fontSize: 13 }}>{joinRosterValue(roster, c.id, p.name) || "—"}</td>
                  ))}
                  {FIELDS.map((f) => (
                    <td key={f.key} className={"num " + (f.kind === "miss" ? "miss" : f.kind === "good" ? "good" : "")} style={{ textAlign: "center", padding: "14px 4px" }}>{p[f.key] || 0}</td>
                  ))}
                  <td className="rate num">{fmtRate(passRate(p))}</td>
                </tr>
              ))}
            </tbody>
          </table>
        </div>
      )}
      <div className="usa-empty" style={{ textAlign: "left", fontSize: 12, marginTop: 12 }}>
        選手は名前で名寄せして合計しています。同じ選手は各試合で同じ名前で登録してください。列見出しをタップすると、その項目で並び替えできます。
      </div>
    </>
  );
}

// ---- settings (⚙️ 設定) view ----

const PRESET_COLORS = ["#1B4332", "#0B4F6C", "#7A1F2B", "#3D2C8D", "#B5541B", "#1B1B1B", "#2D6A4F", "#B08D00"];

function SettingsView({ state, t, ui, patchUi, setThemeColor, exportRosterCSV, importRosterCSV, exportAllDataCSV, importAllDataCSV }: {
  state: AppState; t: TournamentData; ui: UIState; patchUi: (patch: Partial<UIState>) => void;
  setThemeColor: (color: string | undefined) => void;
  exportRosterCSV: (roster: RosterData, tournamentName: string) => void;
  importRosterCSV: (file: File) => void;
  exportAllDataCSV: () => void;
  importAllDataCSV: (file: File) => void;
}) {
  const color = state.themeColor || DEFAULT_PITCH;
  return (
    <>
      <div className="usa-panel">
        <div className="usa-panel-title">🎨 ヘッダーの色（チームカラー）</div>
        <div style={{ display: "flex", alignItems: "center", gap: 10, marginBottom: 10, flexWrap: "wrap" }}>
          <input type="color" value={color} onChange={(e) => setThemeColor(e.target.value)} style={{ width: 44, height: 34, padding: 0, border: "1px solid var(--usa-line)", borderRadius: 8, background: "none" }} />
          {PRESET_COLORS.map((c) => (
            <button key={c} onClick={() => setThemeColor(c)} title={c}
              style={{ width: 26, height: 26, borderRadius: "50%", background: c, border: c === color ? "2px solid var(--usa-ink)" : "1px solid var(--usa-line)", cursor: "pointer" }} />
          ))}
          <button className="usa-btn ghost" onClick={() => setThemeColor(undefined)}>初期値に戻す</button>
        </div>
        <div className="usa-panel-hint" style={{ marginBottom: 0 }}>選んだ色はこのアプリ全体（すべての大会）のヘッダーに適用されます。</div>
      </div>

      <div className="usa-panel">
        <div className="usa-panel-title">📋 選手名簿の入出力（{t.name}）</div>
        <div className="usa-panel-hint">名簿の全列（背番号・名前・追加した列すべて）をCSVで書き出せます。取り込みは1列目→背番号、2列目→名前として扱います。ヘッダー行があれば見出し名で列を自動作成、無ければそのままの順番で既存の列に取り込みます（すでにある名前の選手は内容を上書き更新します）。表計算ソフトの表を選手名簿画面の左上のセルに直接貼り付けることもできます。</div>
        <div className="usa-panel-actions" style={{ justifyContent: "flex-start", marginBottom: 10 }}>
          <button className="usa-btn primary" onClick={() => exportRosterCSV(t.roster, t.name)}>CSV書き出し</button>
        </div>
        <div className="file-input-wrap">
          <input type="file" accept=".csv,text/csv" onChange={(e) => patchUi({ rosterCsvFile: e.target.files && e.target.files[0] ? e.target.files[0] : null })} />
        </div>
        <div className="usa-panel-actions">
          <button className="usa-btn primary" onClick={() => ui.rosterCsvFile && importRosterCSV(ui.rosterCsvFile)}>取り込む</button>
        </div>
      </div>

      <div className="usa-panel">
        <div className="usa-panel-title">💾 全大会・全試合データの入出力（バックアップ）</div>
        <div className="usa-panel-hint">アプリ内のすべての大会・試合・選手のスタッツを1つのCSVにまとめて書き出し／取り込みできます。データは端末のブラウザ内だけに保存されているため、機種変更やブラウザの変更前にこのバックアップを取っておくことをおすすめします。取り込みは大会名・試合名・選手名が一致するデータを上書き、無ければ新規作成します。</div>
        <div className="usa-panel-actions" style={{ justifyContent: "flex-start", marginBottom: 10 }}>
          <button className="usa-btn primary" onClick={exportAllDataCSV}>全データCSV書き出し</button>
        </div>
        <div className="file-input-wrap">
          <input type="file" accept=".csv,text/csv" onChange={(e) => patchUi({ fullCsvFile: e.target.files && e.target.files[0] ? e.target.files[0] : null })} />
        </div>
        <div className="usa-panel-actions">
          <button className="usa-btn primary" onClick={() => ui.fullCsvFile && importAllDataCSV(ui.fullCsvFile)}>取り込む</button>
        </div>
      </div>
    </>
  );
}

// ---- roster (選手名簿) view ----

function RosterView({ roster, ui, patchUi, deleteRosterRow, updateRosterCell, addRosterColumn, renameRosterColumn, deleteRosterColumn, importRosterCSV, pasteRosterGrid }: {
  roster: RosterData; ui: UIState; patchUi: (patch: Partial<UIState>) => void;
  deleteRosterRow: (id: string) => void; updateRosterCell: (rowId: string, colId: string, value: string) => void;
  addRosterColumn: (name: string) => void; renameRosterColumn: (colId: string, name: string) => void; deleteRosterColumn: (colId: string) => void;
  importRosterCSV: (file: File) => void; pasteRosterGrid: (anchorRow: number, anchorCol: number, grid: string[][]) => void;
}) {
  const fileInputRef = useRef<HTMLInputElement | null>(null);

  const handleCellPaste = (rowIndex: number, colIndex: number) => (e: React.ClipboardEvent<HTMLInputElement>) => {
    const text = e.clipboardData.getData("text");
    if (!text.includes("\t") && !text.includes("\n") && !text.includes("\r")) return; // 単一値なら通常の貼り付けに任せる
    e.preventDefault();
    const grid = text.split(/\r\n|\n|\r/).filter((l, i, arr) => !(i === arr.length - 1 && l === "")).map((line) => line.split("\t"));
    pasteRosterGrid(rowIndex, colIndex, grid);
  };

  return (
    <>
      <div className="usa-empty" style={{ textAlign: "left", fontSize: 12, margin: "0 16px 12px" }}>
        名簿は表形式で編集できます。列は自由に追加できますが、スタッツで使われるのは最初の2列（背番号・名前）だけです。「📋 コピー」で表の内容をタブ区切りテキストとしてコピーでき、表計算ソフトにそのまま貼り付けられます。逆に、表計算ソフトの内容をコピーしてこの表のセルに貼り付けることもできます（貼り付けたセルを起点に展開されます）。「📄 CSVを読み込む」で、ヘッダー行がある／ないどちらのCSVファイルも取り込めます。
      </div>
      <div className="usa-action-row">
        <button className="usa-add-cta" onClick={() => fileInputRef.current?.click()}>📄 CSVを読み込む</button>
        <input
          ref={fileInputRef} type="file" accept=".csv,text/csv" style={{ display: "none" }}
          onChange={(e) => {
            const f = e.target.files && e.target.files[0];
            if (f) importRosterCSV(f);
            e.target.value = "";
          }}
        />
      </div>
      <div className="usa-table-wrap">
        <table className="usa-stats usa-roster-table">
          <thead>
            <tr>
              {roster.columns.map((c) => (
                <RosterHeaderCell key={c.id} col={c} onRename={renameRosterColumn} onDelete={deleteRosterColumn} />
              ))}
              <th style={{ minWidth: 40 }} />
              <th style={{ minWidth: 90 }}>
                {ui.addingRosterColumn ? (
                  <NewColumnForm onConfirm={addRosterColumn} onCancel={() => patchUi({ addingRosterColumn: false })} />
                ) : (
                  <button className="usa-tool-btn" style={{ padding: "6px 10px", fontSize: 12 }} onClick={() => patchUi({ addingRosterColumn: true })}>＋ 列</button>
                )}
              </th>
            </tr>
          </thead>
          <tbody>
            {roster.rows.map((r, rowIndex) => (
              <tr key={r.id}>
                {roster.columns.map((c, colIndex) => (
                  <td key={c.id} style={{ padding: 4 }}>
                    <input
                      className={c.id === "number" ? "num" : undefined}
                      value={r.values[c.id] || ""}
                      onChange={(e) => updateRosterCell(r.id, c.id, e.target.value)}
                      onPaste={handleCellPaste(rowIndex, colIndex)}
                      style={{ width: "100%", minWidth: c.id === "number" ? 60 : 100, padding: "8px 9px", borderRadius: 8, border: "1px solid var(--usa-line)", background: "var(--usa-chalk)", color: "var(--usa-ink)", fontSize: 13 }}
                    />
                  </td>
                ))}
                <td style={{ textAlign: "center" }}>
                  <button className="usa-trash-btn" title="削除" onClick={() => deleteRosterRow(r.id)}>🗑</button>
                </td>
                <td />
              </tr>
            ))}
          </tbody>
        </table>
      </div>
      {roster.rows.length === 0 && (
        <div className="usa-empty">まだ選手が登録されていません。「＋ 行を追加」で選手を追加しましょう。表計算ソフトの表を一番左上のセルに貼り付けることもできます。</div>
      )}
    </>
  );
}

function RosterHeaderCell({ col, onRename, onDelete }: { col: RosterColumn; onRename: (id: string, name: string) => void; onDelete: (id: string) => void }) {
  const [editing, setEditing] = useState(false);
  const [val, setVal] = useState(col.name);
  if (col.locked) {
    return <th style={{ minWidth: 80 }}>{col.name}</th>;
  }
  if (editing) {
    return (
      <th style={{ minWidth: 100 }}>
        <input
          autoFocus value={val} onChange={(e) => setVal(e.target.value)}
          onBlur={() => { onRename(col.id, val); setEditing(false); }}
          onKeyDown={(e) => { if (e.key === "Enter") { onRename(col.id, val); setEditing(false); } }}
          style={{ width: "100%", padding: "4px 6px", borderRadius: 6, border: "1px solid var(--usa-line)", fontSize: 11, textAlign: "center" }}
        />
      </th>
    );
  }
  return (
    <th style={{ minWidth: 100 }}>
      <span style={{ cursor: "pointer" }} onClick={() => { setVal(col.name); setEditing(true); }}>{col.name}</span>
      <button className="x" style={{ marginLeft: 4, opacity: 0.6 }} onClick={() => onDelete(col.id)}>✕</button>
    </th>
  );
}

function NewColumnForm({ onConfirm, onCancel, placeholder }: { onConfirm: (name: string) => void; onCancel: () => void; placeholder?: string }) {
  const [val, setVal] = useState("");
  return (
    <div style={{ display: "flex", gap: 4 }}>
      <input
        autoFocus value={val} placeholder={placeholder || "列名"} onChange={(e) => setVal(e.target.value)}
        onKeyDown={(e) => { if (e.key === "Enter") onConfirm(val); }}
        style={{ width: 90, padding: "4px 6px", borderRadius: 6, border: "1px solid var(--usa-line)", fontSize: 11 }}
      />
      <button className="x" style={{ opacity: 1 }} onClick={() => onConfirm(val)}>✔</button>
      <button className="x" onClick={onCancel}>✕</button>
    </div>
  );
}

function AwardRow({ award, aggRows, onSetWinner, onRename, onDelete }: {
  award: TournamentAward; aggRows: AggRow[];
  onSetWinner: (awardId: string, playerName: string) => void;
  onRename: (awardId: string, name: string) => void; onDelete: (awardId: string) => void;
}) {
  const [editing, setEditing] = useState(false);
  const [val, setVal] = useState(award.name);
  return (
    <div className="usa-roster-row">
      {editing ? (
        <input
          autoFocus value={val} onChange={(e) => setVal(e.target.value)}
          onBlur={() => { onRename(award.id, val); setEditing(false); }}
          onKeyDown={(e) => { if (e.key === "Enter") { onRename(award.id, val); setEditing(false); } }}
          style={{ width: 100, padding: "6px 8px", borderRadius: 8, border: "1px solid var(--usa-line)", fontSize: 13 }}
        />
      ) : (
        <span style={{ minWidth: 100, fontWeight: 700, cursor: "pointer" }} onClick={() => { setVal(award.name); setEditing(true); }}>{award.name}</span>
      )}
      <select
        value={award.playerName}
        onChange={(e) => onSetWinner(award.id, e.target.value)}
        style={{ flex: 1, padding: "6px 8px", borderRadius: 8, border: "1px solid var(--usa-line)", background: "var(--usa-chalk)", color: "var(--usa-ink)", fontSize: 13 }}
      >
        <option value="">未選出</option>
        {aggRows.map((r) => <option key={r.name} value={r.name}>{r.name}</option>)}
      </select>
      <button className="usa-trash-btn" title="この賞を削除" onClick={() => onDelete(award.id)}>🗑</button>
    </div>
  );
}

function TotalsRow({ players }: { players: Player[] }) {
  const sums: PlayerStats = { touch: 0, throwMiss: 0, catchMiss: 0, block: 0, goal: 0, assist: 0 };
  players.forEach((p) => (Object.keys(sums) as StatKey[]).forEach((k) => { sums[k] += p[k] || 0; }));
  return (
    <tr>
      <td className="sticky-no" />
      <td className="sticky-name">合計</td>
      {FIELDS.map((f) => <td key={f.key} className="num">{sums[f.key]}</td>)}
      <td className="num">—</td>
    </tr>
  );
}

function PlayerRow({ p, ui, patchUi, bump, mode, updatePlayer, deletePlayer, toggleMom }: {
  p: Player; ui: UIState; patchUi: (patch: Partial<UIState>) => void;
  bump: (id: string, field: StatKey, delta: number) => void; mode: "add" | "sub";
  updatePlayer: (id: string, name: string, number: string) => void; deletePlayer: (id: string) => void;
  toggleMom: (id: string) => void;
}) {
  if (ui.confirmDeletePlayer === p.id) {
    return (
      <tr className="confirm-row">
        <td className="sticky-no num">{p.number || ""}</td>
        <td colSpan={FIELDS.length + 2}>
          <div className="confirm-inline">
            <span>{p.name} を削除しますか？</span>
            <button className="usa-btn danger" onClick={() => deletePlayer(p.id)}>削除</button>
            <button className="usa-btn ghost" onClick={() => patchUi({ confirmDeletePlayer: null })}>キャンセル</button>
          </div>
        </td>
      </tr>
    );
  }
  if (ui.editingPlayerId === p.id) {
    return <EditRow p={p} onSave={updatePlayer} onCancel={() => patchUi({ editingPlayerId: null })} />;
  }
  return (
    <tr className={p.mom ? "usa-mom-row" : undefined}>
      <td className="sticky-no">
        <button className="usa-no-btn" onClick={() => patchUi({ editingPlayerId: p.id })}>
          {p.number ? <span className="no-value num">{p.number}</span> : <span className="no-value empty">―</span>}
        </button>
      </td>
      <td className="sticky-name">
        <div className="usa-player-row-actions">
          <button className={"usa-mom-btn" + (p.mom ? " active" : "")} title="マンオブザマッチ" onClick={() => toggleMom(p.id)}>{p.mom ? "⭐" : "☆"}</button>
          <button className="usa-name-btn" onClick={() => patchUi({ editingPlayerId: p.id })}>
            <div className="usa-player-name">{p.name}{p.mom ? <span className="usa-mom-badge">MOM</span> : null}</div>
          </button>
          <button className="usa-trash-btn" title="削除" onClick={() => patchUi({ confirmDeletePlayer: p.id })}>🗑</button>
        </div>
      </td>
      {FIELDS.map((f) => (
        <td key={f.key} className={"cell " + (f.kind === "miss" ? "miss" : f.kind === "good" ? "good" : "")}>
          <button className="usa-cell-btn num" onClick={() => bump(p.id, f.key, mode === "sub" ? -1 : 1)}>{p[f.key] || 0}</button>
        </td>
      ))}
      <td className="rate num">{fmtRate(passRate(p))}</td>
    </tr>
  );
}

function EditRow({ p, onSave, onCancel }: { p: Player; onSave: (id: string, name: string, number: string) => void; onCancel: () => void }) {
  const [num, setNum] = useState(p.number);
  const [name, setName] = useState(p.name);
  return (
    <tr className="inline-form-row">
      <td className="sticky-no">
        <input className="num" value={num} placeholder="番号" onChange={(e) => setNum(e.target.value)}
          style={{ width: 44, padding: 6, borderRadius: 8, border: "1px solid var(--usa-line)", background: "var(--usa-chalk)", color: "var(--usa-ink)", fontSize: 12, textAlign: "center" }} />
      </td>
      <td colSpan={FIELDS.length + 2}>
        <div style={{ display: "flex", gap: 6, alignItems: "center" }}>
          <input autoFocus value={name} placeholder="名前" onChange={(e) => setName(e.target.value)}
            onKeyDown={(e) => { if (e.key === "Enter") onSave(p.id, name, num); }}
            style={{ flex: 1, padding: "8px 10px", borderRadius: 8, border: "1px solid var(--usa-line)", background: "var(--usa-chalk)", color: "var(--usa-ink)", fontSize: 13 }} />
          <button className="usa-btn primary" onClick={() => onSave(p.id, name, num)}>保存</button>
          <button className="usa-btn ghost" onClick={onCancel}>キャンセル</button>
        </div>
      </td>
    </tr>
  );
}

// ---- lineup filter / saved groups ----

function FilterBar({ match, t, ui, patchUi, applyFilter, clearFilter, saveGroup, updateGroup, deleteGroup, showToast }: {
  match: MatchData; t: TournamentData; ui: UIState; patchUi: (patch: Partial<UIState>) => void;
  applyFilter: (names: string[]) => void; clearFilter: () => void;
  saveGroup: (name: string, memberNames: string[]) => void;
  updateGroup: (groupId: string, memberNames: string[]) => void;
  deleteGroup: (groupId: string) => void;
  showToast: (msg: string) => void;
}) {
  if (ui.filterOpen) {
    return (
      <FilterPanel
        match={match} t={t} ui={ui} patchUi={patchUi}
        applyFilter={applyFilter} saveGroup={saveGroup} updateGroup={updateGroup} deleteGroup={deleteGroup}
        showToast={showToast}
      />
    );
  }
  if (match.activeFilterNames && match.activeFilterNames.length) {
    return (
      <div className="usa-filter-bar">
        <span className="num">🔍 出場 {match.activeFilterNames.length}人を表示中</span>
        <button className="usa-btn ghost" onClick={() => openFilterPanel(match, patchUi)}>変更</button>
        <button className="usa-btn ghost" onClick={clearFilter}>解除</button>
      </div>
    );
  }
  return (
    <div className="usa-filter-bar">
      <button className="usa-btn ghost" onClick={() => openFilterPanel(match, patchUi)}>🔍 出場メンバーを絞り込む</button>
    </div>
  );
}

function openFilterPanel(match: MatchData, patchUi: (patch: Partial<UIState>) => void) {
  const draft: Record<string, boolean> = {};
  if (match.activeFilterNames && match.activeFilterNames.length) {
    match.players.forEach((p) => { draft[p.id] = (match.activeFilterNames as string[]).includes(p.name.trim()); });
  } else {
    match.players.forEach((p) => { draft[p.id] = true; });
  }
  patchUi({ filterOpen: true, filterDraft: draft, filterLoadedGroupId: null, savingGroupNameOpen: false });
}

function FilterPanel({ match, t, ui, patchUi, applyFilter, saveGroup, updateGroup, deleteGroup, showToast }: {
  match: MatchData; t: TournamentData; ui: UIState; patchUi: (patch: Partial<UIState>) => void;
  applyFilter: (names: string[]) => void;
  saveGroup: (name: string, memberNames: string[]) => void;
  updateGroup: (groupId: string, memberNames: string[]) => void;
  deleteGroup: (groupId: string) => void;
  showToast: (msg: string) => void;
}) {
  const [groupName, setGroupName] = useState("");
  const groups = t.groups || [];
  const count = match.players.filter((p) => ui.filterDraft[p.id]).length;

  const loadGroup = (g: MatchGroup) => {
    const draft: Record<string, boolean> = {};
    match.players.forEach((p) => { draft[p.id] = g.memberNames.includes(p.name.trim()); });
    patchUi({ filterDraft: draft, filterLoadedGroupId: g.id });
  };

  const apply = () => {
    const names = match.players.filter((p) => ui.filterDraft[p.id]).map((p) => p.name.trim());
    if (!names.length) { showToast("少なくとも1人選択してください"); return; }
    patchUi({ filterOpen: false, filterDraft: {}, filterLoadedGroupId: null, savingGroupNameOpen: false });
    applyFilter(names);
  };

  const confirmSaveGroup = () => {
    const name = groupName.trim();
    if (!name) { showToast("グループ名を入力してください"); return; }
    const names = match.players.filter((p) => ui.filterDraft[p.id]).map((p) => p.name.trim());
    if (!names.length) { showToast("少なくとも1人選択してください"); return; }
    saveGroup(name, names);
    setGroupName("");
    patchUi({ savingGroupNameOpen: false });
    showToast("グループを保存しました");
  };

  const doUpdateGroup = () => {
    if (!ui.filterLoadedGroupId) return;
    const names = match.players.filter((p) => ui.filterDraft[p.id]).map((p) => p.name.trim());
    if (!names.length) { showToast("少なくとも1人選択してください"); return; }
    updateGroup(ui.filterLoadedGroupId, names);
    showToast("グループを更新しました");
  };

  return (
    <div className="usa-panel">
      <div className="usa-panel-title">出場メンバーを選択</div>
      {groups.length > 0 && (
        <div className="usa-group-chip-row">
          {groups.map((g) => (
            ui.confirmDeleteGroup === g.id ? (
              <span key={g.id} className="usa-chip-confirm">
                「{g.name}」を削除？ <button onClick={() => deleteGroup(g.id)}>削除</button> <button onClick={() => patchUi({ confirmDeleteGroup: null })}>キャンセル</button>
              </span>
            ) : (
              <span key={g.id} className={"usa-group-chip-wrap" + (ui.filterLoadedGroupId === g.id ? " active" : "")}>
                <button className="usa-group-chip" onClick={() => loadGroup(g)}>{g.name} ({g.memberNames.length})</button>
                <button className="usa-group-chip-x" onClick={() => patchUi({ confirmDeleteGroup: g.id })}>✕</button>
              </span>
            )
          ))}
        </div>
      )}
      <div className="usa-roster-list">
        {match.players.map((p) => (
          <label key={p.id} className="usa-roster-row">
            <input type="checkbox" checked={!!ui.filterDraft[p.id]} onChange={() => patchUi({ filterDraft: { ...ui.filterDraft, [p.id]: !ui.filterDraft[p.id] } })} />
            <span>{p.name} {p.number && <span className="num" style={{ color: "var(--usa-ink-soft)" }}>#{p.number}</span>}</span>
          </label>
        ))}
      </div>
      <div className="usa-panel-actions" style={{ justifyContent: "space-between" }}>
        <div style={{ display: "flex", gap: 6 }}>
          <button className="usa-btn ghost" onClick={() => patchUi({ filterDraft: Object.fromEntries(match.players.map((p) => [p.id, true])) })}>全選択</button>
          <button className="usa-btn ghost" onClick={() => patchUi({ filterDraft: {} })}>全解除</button>
        </div>
        <div style={{ display: "flex", gap: 6 }}>
          <button className="usa-btn ghost" onClick={() => patchUi({ filterOpen: false, filterDraft: {}, filterLoadedGroupId: null, savingGroupNameOpen: false })}>キャンセル</button>
          <button className="usa-btn primary" onClick={apply}>表示する ({count})</button>
        </div>
      </div>
      {ui.savingGroupNameOpen ? (
        <>
          <div className="usa-panel-row" style={{ marginTop: 4 }}>
            <input value={groupName} placeholder="グループ名（例: オフェンス組）" onChange={(e) => setGroupName(e.target.value)} />
          </div>
          <div className="usa-panel-actions">
            <button className="usa-btn ghost" onClick={() => { setGroupName(""); patchUi({ savingGroupNameOpen: false }); }}>キャンセル</button>
            <button className="usa-btn primary" onClick={confirmSaveGroup}>保存</button>
          </div>
        </>
      ) : (
        <div className="usa-panel-actions" style={{ justifyContent: "flex-start", flexWrap: "wrap", marginTop: 4 }}>
          {ui.filterLoadedGroupId && <button className="usa-btn ghost" onClick={doUpdateGroup}>このグループを更新</button>}
          <button className="usa-btn ghost" onClick={() => patchUi({ savingGroupNameOpen: true })}>＋ グループとして保存</button>
        </div>
      )}
    </div>
  );
}

// ---- add player / copy ----

function AddPlayerArea({ ui, patchUi, addPlayer, allOtherMatches, copyPlayersFrom, findMatchByKey, roster, addPlayersFromRoster }: {
  ui: UIState; patchUi: (patch: Partial<UIState>) => void;
  addPlayer: (name: string, number: string) => void;
  allOtherMatches: () => { key: string; tournamentName: string; match: MatchData }[];
  copyPlayersFrom: (key: string | null, selected: Record<string, boolean>) => void;
  findMatchByKey: (key: string) => MatchData | null;
  roster: RosterData;
  addPlayersFromRoster: (selected: Record<string, boolean>) => void;
}) {
  if (ui.copyOpen) {
    return <CopyPanel ui={ui} patchUi={patchUi} allOtherMatches={allOtherMatches} copyPlayersFrom={copyPlayersFrom} findMatchByKey={findMatchByKey} />;
  }
  if (ui.rosterPickOpen) {
    return <RosterPickerPanel roster={roster} ui={ui} patchUi={patchUi} addPlayersFromRoster={addPlayersFromRoster} />;
  }
  if (!ui.addPlayerOpen) {
    const others = allOtherMatches();
    return (
      <div className="usa-action-row">
        <button className="usa-add-cta" onClick={() => patchUi({ addPlayerOpen: true })}>＋ 選手を追加</button>
        {roster.rows.length > 0 && (
          <button className="usa-add-cta" onClick={() => patchUi({ rosterPickOpen: true, rosterPickSelected: Object.fromEntries(roster.rows.map((r) => [r.id, true])) })}>
            👥 名簿から
          </button>
        )}
        {others.length > 0 && <button className="usa-add-cta" onClick={() => patchUi({ copyOpen: true, copySourceKey: null, copySelected: {} })}>📋 他の試合から</button>}
      </div>
    );
  }
  return <AddPlayerForm onAdd={addPlayer} onCancel={() => patchUi({ addPlayerOpen: false })} />;
}

function AddPlayerForm({ onAdd, onCancel }: { onAdd: (name: string, number: string) => void; onCancel: () => void }) {
  const [num, setNum] = useState("");
  const [name, setName] = useState("");
  return (
    <div className="usa-panel">
      <div className="usa-panel-title">選手を追加</div>
      <div className="usa-panel-row">
        <input className="num-input num" value={num} placeholder="番号" inputMode="numeric" onChange={(e) => setNum(e.target.value)} />
        <input autoFocus value={name} placeholder="名前" onChange={(e) => setName(e.target.value)} onKeyDown={(e) => { if (e.key === "Enter") onAdd(name, num); }} />
      </div>
      <div className="usa-panel-actions">
        <button className="usa-btn ghost" onClick={onCancel}>キャンセル</button>
        <button className="usa-btn primary" onClick={() => onAdd(name, num)}>追加</button>
      </div>
    </div>
  );
}

function CopyPanel({ ui, patchUi, allOtherMatches, copyPlayersFrom, findMatchByKey }: {
  ui: UIState; patchUi: (patch: Partial<UIState>) => void;
  allOtherMatches: () => { key: string; tournamentName: string; match: MatchData }[];
  copyPlayersFrom: (key: string | null, selected: Record<string, boolean>) => void;
  findMatchByKey: (key: string) => MatchData | null;
}) {
  const others = allOtherMatches();
  if (!ui.copySourceKey) {
    return (
      <div className="usa-panel">
        <div className="usa-panel-title">他の試合からコピー</div>
        {others.length === 0 ? (
          <div className="usa-panel-hint">コピー元にできる試合がありません。</div>
        ) : (
          others.map((o) => (
            <div key={o.key} className="usa-tab" style={{ width: "100%", justifyContent: "space-between", borderRadius: 10, marginBottom: 6, color: "var(--usa-ink)", background: "var(--usa-chalk)", borderColor: "var(--usa-line)" }}
              onClick={() => patchUi({ copySourceKey: o.key, copySelected: Object.fromEntries(o.match.players.map((p) => [p.id, true])) })}>
              <span>{o.tournamentName} ▸ {o.match.name}</span><span>{o.match.players.length}人</span>
            </div>
          ))
        )}
        <div className="usa-panel-actions">
          <button className="usa-btn ghost" onClick={() => patchUi({ copyOpen: false, copySourceKey: null, copySelected: {} })}>キャンセル</button>
        </div>
      </div>
    );
  }
  const source = findMatchByKey(ui.copySourceKey);
  if (!source) return null;
  const count = Object.values(ui.copySelected).filter(Boolean).length;
  return (
    <div className="usa-panel">
      <div className="usa-panel-title">{source.name} から選手を選択</div>
      <div className="usa-roster-list">
        {source.players.map((p) => (
          <label key={p.id} className="usa-roster-row">
            <input type="checkbox" checked={!!ui.copySelected[p.id]} onChange={() => patchUi({ copySelected: { ...ui.copySelected, [p.id]: !ui.copySelected[p.id] } })} />
            <span>{p.name} {p.number && <span className="num" style={{ color: "var(--usa-ink-soft)" }}>#{p.number}</span>}</span>
          </label>
        ))}
      </div>
      <div className="usa-panel-actions" style={{ justifyContent: "space-between" }}>
        <div style={{ display: "flex", gap: 6 }}>
          <button className="usa-btn ghost" onClick={() => patchUi({ copySelected: Object.fromEntries(source.players.map((p) => [p.id, true])) })}>全選択</button>
          <button className="usa-btn ghost" onClick={() => patchUi({ copySelected: {} })}>全解除</button>
        </div>
        <div style={{ display: "flex", gap: 6 }}>
          <button className="usa-btn ghost" onClick={() => patchUi({ copySourceKey: null, copySelected: {} })}>戻る</button>
          <button className="usa-btn primary" onClick={() => copyPlayersFrom(ui.copySourceKey, ui.copySelected)}>コピーする ({count})</button>
        </div>
      </div>
    </div>
  );
}

function RosterPickerPanel({ roster, ui, patchUi, addPlayersFromRoster }: {
  roster: RosterData; ui: UIState; patchUi: (patch: Partial<UIState>) => void;
  addPlayersFromRoster: (selected: Record<string, boolean>) => void;
}) {
  const count = Object.values(ui.rosterPickSelected).filter(Boolean).length;
  return (
    <div className="usa-panel">
      <div className="usa-panel-title">選手名簿から出場選手を選択</div>
      {roster.rows.length === 0 ? (
        <div className="usa-panel-hint">選手名簿に選手が登録されていません。「📋 選手名簿」で登録してください。</div>
      ) : (
        <div className="usa-roster-list">
          {roster.rows.map((r) => {
            const name = r.values["name"] || "";
            const number = r.values["number"] || "";
            return (
              <label key={r.id} className="usa-roster-row">
                <input type="checkbox" checked={!!ui.rosterPickSelected[r.id]} onChange={() => patchUi({ rosterPickSelected: { ...ui.rosterPickSelected, [r.id]: !ui.rosterPickSelected[r.id] } })} />
                <span>{name || <span style={{ color: "var(--usa-ink-soft)" }}>（名前未入力）</span>} {number && <span className="num" style={{ color: "var(--usa-ink-soft)" }}>#{number}</span>}</span>
              </label>
            );
          })}
        </div>
      )}
      <div className="usa-panel-actions" style={{ justifyContent: "space-between" }}>
        <div style={{ display: "flex", gap: 6 }}>
          <button className="usa-btn ghost" onClick={() => patchUi({ rosterPickSelected: Object.fromEntries(roster.rows.map((r) => [r.id, true])) })}>全選択</button>
          <button className="usa-btn ghost" onClick={() => patchUi({ rosterPickSelected: {} })}>全解除</button>
        </div>
        <div style={{ display: "flex", gap: 6 }}>
          <button className="usa-btn ghost" onClick={() => patchUi({ rosterPickOpen: false, rosterPickSelected: {} })}>キャンセル</button>
          <button className="usa-btn primary" onClick={() => addPlayersFromRoster(ui.rosterPickSelected)}>追加する ({count})</button>
        </div>
      </div>
    </div>
  );
}

// ---- help modal ----

function HelpModal({ onClose }: { onClose: () => void }) {
  return (
    <div className="usa-modal-backdrop" onClick={onClose}>
      <div className="usa-modal-sheet" onClick={(e) => e.stopPropagation()}>
        <div className="usa-modal-head">
          <h3>使い方</h3>
          <button className="usa-icon-btn" style={{ background: "var(--usa-chalk)", color: "var(--usa-ink)" }} onClick={onClose}>✕</button>
        </div>

        <div className="usa-help-section">
          <div className="usa-help-title">🔒 データの保存について</div>
          <p>入力したデータ（大会・試合・選手・スタッツなど）は、サーバーには一切送信されず、<b>お使いのブラウザの中だけ</b>に保存されます。ヘッダー右上の「自動保存」表示は、この端末内への保存が完了したことを示しています。</p>
          <p>そのため、ブラウザの履歴やサイトデータを消去したり、別の端末・別のブラウザで開いたりすると、データは引き継がれません。機種変更やブラウザの変更の前には、「⚙️ 設定」の「全大会・全試合データの入出力」からCSVでバックアップを取り、新しい環境で取り込んでください。</p>
        </div>

        <div className="usa-help-section">
          <div className="usa-help-title">🏆 大会と試合</div>
          <p>データは「大会（トーナメントや練習会など）」の中に複数の「試合」がある構成です。ヘッダーの上段タブで大会を切り替え、下段タブで大会内の試合を切り替えます。「＋ 新しい大会」「＋ 新しい試合」で追加、タブの✕で削除できます。名前の右にある✎で名称を変更できます。</p>
        </div>

        <div className="usa-help-section">
          <div className="usa-help-title">✏️ スタッツの入力</div>
          <p>選手を試合に追加すると、タッチ数・スローミス・キャッチミス・ブロック・ゴール・アシストの数字をタップするだけでカウントアップされます。フッターの「＋1」「－1」を切り替えると、タップで減算もできます。「元に戻す」で直近の操作を最大10件まで1つずつ取り消せます。</p>
          <p>選手名の横の☆をタップすると、その試合の「マンオブザマッチ（MOM）」を1人だけ設定できます。</p>
        </div>

        <div className="usa-help-section">
          <div className="usa-help-title">👥 選手の追加</div>
          <p>「＋ 選手を追加」で個別に登録できるほか、「他の試合から」で別の試合の選手をまとめてコピー、「CSVから登録」でCSVファイル（ヘッダ無し、1行に「背番号,選手名」）から一括登録できます。</p>
        </div>

        <div className="usa-help-section">
          <div className="usa-help-title">📊 大会全体の集計</div>
          <p>大会内の全試合の合計スタッツを確認できます。列見出しをタップするとその項目で並び替え、「名簿の列を表示」で選手名簿の追加情報（学年など）を表示・絞り込みできます。「🏅 個人賞」でMVPなどの受賞者を選手名から選んで設定できます（1人が複数の賞を受賞してもかまいません）。</p>
        </div>

        <div className="usa-help-section">
          <div className="usa-help-title">📋 選手名簿</div>
          <p>大会ごとに選手名簿を表形式で管理できます。背番号・名前は固定の列、それ以外の列（学年・ポジションなど）は自由に追加できます。「📋 コピー」で表全体をタブ区切りテキストとしてコピーし、表計算ソフトに貼り付けられます。</p>
        </div>

        <div className="usa-help-section">
          <div className="usa-help-title">⚙️ 設定</div>
          <p>ヘッダーの色をチームカラーに変更できます。また、選手名簿や全データをCSVで書き出し・取り込みできます。</p>
        </div>

        <div className="usa-help-section">
          <div className="usa-help-title">📄 CSV / 🖨️ PDF書き出し</div>
          <p>試合や大会全体の集計は、フッターの「CSV書き出し」でファイルとして保存、「PDF」で印刷（PDF保存）できます。</p>
        </div>
      </div>
    </div>
  );
}

